public static class Services
{
    static class Slot<T>
    {
        public static T? Value;
        public static bool IsSet;
    }

    public static void Set<T>(T value)
    {
        Slot<T>.Value = value;
        Slot<T>.IsSet = true;
    }

    public static T Get<T>() => Slot<T>.IsSet ? Slot<T>.Value! : throw new InvalidOperationException($"no {typeof(T).Name} set");

    public static bool Has<T>() => Slot<T>.IsSet;

    public static void Clear<T>()
    {
        Slot<T>.Value = default;
        Slot<T>.IsSet = false;
    }
}

unitTests:
Test("set and get per type", () =>
{
    Services.Set("hello");
    Services.Set(42);
    CheckEq(Services.Get<string>(), "hello");
    CheckEq(Services.Get<int>(), 42);
});

Test("types do not mix", () =>
{
    Services.Clear<object>();
    Services.Set("only a string");
    Check(!Services.Has<object>());
    Check(Services.Has<string>());
});

Test("missing and cleared", () =>
{
    Services.Clear<double>();
    CheckThrows<InvalidOperationException>(() => Services.Get<double>());
    Services.Set(1.5);
    Services.Clear<double>();
    Check(!Services.Has<double>());
});

Test("a stored zero or null still counts as set", () =>
{
    Services.Set(0L);
    Check(Services.Has<long>());
    Services.Set<string?>(null);
    Check(Services.Has<string?>());
});

